WITH web_events_by_session AS (SELECT session_id, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT(CASE WHEN event_type = 'page_view' THEN 1 END) AS page_view_count FROM web_events GROUP BY session_id) SELECT s.id, s.started_at, webs.avg_duration_sec, webs.page_view_count FROM sessions s INNER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.avg_duration_sec > 73 ORDER BY s.id DESC, webs.avg_duration_sec ASC;
